import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Route, Routes, Link, useNavigate } from 'react-router-dom';
import Home from './components/Home';
import MotoristasList from './components/MotoristasList';
import BuscarMotorista from './components/BuscarMotorista';
import CadastrarMotorista from './components/CadastrarMotorista';
import Dashboard from './components/Dashboard';
import Login from './components/Login';
import Perfil from './components/Perfil';
import './styles/global.css';

const App = () => {
    const [user, setUser] = useState(null);

    return (
        <Router>
            <AppContent user={user} setUser={setUser} />
        </Router>
    );
};

// Componente principal com sidebar e menu hamburguer
const AppContent = ({ user, setUser }) => {
    const [menuAberto, setMenuAberto] = useState(false);
    const navigate = useNavigate();

    useEffect(() => {
        const token = localStorage.getItem('token');
        if (token) {
            setUser({ token });
        }
    }, [setUser]);

    const handleLogout = () => {
        localStorage.removeItem('token');
        setUser(null);
        navigate('/login');
    };

    return (
        <div className="app-container">
            {/* Navbar */}
            <nav className="navbar">
                <h1>🚗 CheckPort</h1>
                <button className="menu-toggle" onClick={() => setMenuAberto(!menuAberto)}>☰</button>
                <div className={`nav-links ${menuAberto ? 'active' : ''}`}>
                    <Link to="/" onClick={() => setMenuAberto(false)}>🏠 Início</Link>
                    {user ? (
                        <>
                            <Link to="/listar" onClick={() => setMenuAberto(false)}>📋 Lista</Link>
                            <Link to="/buscar" onClick={() => setMenuAberto(false)}>🔍 Buscar</Link>
                            <Link to="/cadastrar" onClick={() => setMenuAberto(false)}>➕ Cadastrar</Link>
                            <Link to="/dashboard" onClick={() => setMenuAberto(false)}>📊 Dashboard</Link>
                            <Link to="/perfil" onClick={() => setMenuAberto(false)}>👤 Meu Perfil</Link>
                            <button onClick={handleLogout}>🚪 Sair</button>
                        </>
                    ) : (
                        <Link to="/login">🔐 Login</Link>
                    )}
                </div>
            </nav>

            {/* Sidebar para Desktop */}
            <div className="sidebar">
                <Link to="/listar">📋 Lista</Link>
                <Link to="/buscar">🔍 Buscar</Link>
                <Link to="/cadastrar">➕ Cadastrar</Link>
                <Link to="/dashboard">📊 Dashboard</Link>
                <Link to="/perfil">👤 Meu Perfil</Link>
            </div>

            {/* Conteúdo principal */}
            <div className="main-content">
                <Routes>
                    <Route path="/" element={<Home />} />
                    <Route path="/login" element={<Login setUser={setUser} />} />
                    {user && (
                        <>
                            <Route path="/listar" element={<MotoristasList />} />
                            <Route path="/buscar" element={<BuscarMotorista />} />
                            <Route path="/cadastrar" element={<CadastrarMotorista />} />
                            <Route path="/dashboard" element={<Dashboard />} />
                            <Route path="/perfil" element={<Perfil />} />
                        </>
                    )}
                </Routes>
            </div>
        </div>
    );
};

export default App;
